// Signed text = "<timestamp>.<raw body>", so an old request cannot be replayed with a fresh timestamp.
const item = $input.first();
const headers = item.json.headers ?? {};
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const ts = String(headers['x-securefin-timestamp'] ?? '');
const age = Math.abs(Date.now() / 1000 - Number(ts));
return [{ json: {
  raw,
  signed: `${ts}.${raw}`,
  signature: String(headers['x-securefin-signature'] ?? ''),
  fresh: /^\d{10}$/.test(ts) && age <= 300,
  secret_set: String($env.N8N_WEBHOOK_HMAC_SECRET ?? '').length >= 32,
} }];

// Fails closed: no secret, stale timestamp, bad signature or an unexpected payload all give valid=false.
const j = $input.first().json;
const want = `sha256=${j.expected}`;
let diff = want.length ^ j.signature.length;
for (let i = 0; i < want.length; i++) diff |= want.charCodeAt(i) ^ (j.signature.charCodeAt(i) || 0);
let event = null;
try { event = JSON.parse(j.raw); } catch (e) { event = null; }
const TYPES = ['hold', 'block', 'needs_second_approval', 'bank_change_pending'];
const id = (v) => Number.isInteger(v) && v > 0;
const shaped = !!event && TYPES.includes(event.event_type)
  && typeof event.event_id === 'string' && /^[A-Za-z0-9_.:-]{8,100}$/.test(event.event_id)
  && (event.event_type === 'bank_change_pending' ? id(event.vendor_id) : id(event.payment_request_id));
const valid = j.secret_set && j.fresh && diff === 0 && shaped;
return [{ json: valid ? { valid, event } : { valid } }];

// Only ids, the event type and reason codes leave the system: no amounts, vendor names or bank details.
// The link is built here from APP_BASE_URL, never taken from the payload. There is no approve button:
// approvals happen in the app, through the gateway.
const TEXT = {
  hold: ['Payment on hold', 'دفعة موقوفة للمراجعة'],
  block: ['Payment blocked', 'تم حظر الدفعة'],
  needs_second_approval: ['Second approval needed', 'مطلوب موافقة ثانية'],
  bank_change_pending: ['Vendor bank details changed: waiting period started', 'تغيير بيانات بنك المورد: بدأت فترة الانتظار'],
};
const clean = (s) => String(s).replace(/[\u0000-\u001f]/g, ' ').slice(0, 120);
const html = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const e = $input.first().json.event;
const base = String($env.APP_BASE_URL ?? '').replace(/\/+$/, '');
const vendor = e.event_type === 'bank_change_pending';
const link = vendor ? `${base}/vendors/${e.vendor_id}` : `${base}/payments/${e.payment_request_id}`;
const ref = vendor ? `Vendor #${e.vendor_id}` : `Payment request #${e.payment_request_id}`;
const reasons = (Array.isArray(e.reasons) ? e.reasons : []).slice(0, 3).map(clean);
const [en, ar] = TEXT[e.event_type];
const lines = [
  `${ar}`, `${en}`, '', ref,
  ...(reasons.length ? ['Top reasons / أهم الأسباب:', ...reasons.map((r, i) => `${i + 1}. ${r}`)] : []),
  ...(e.expires_at ? [`Until / حتى: ${clean(e.expires_at)}`] : []),
  '', `Open in SecureFin / افتح في التطبيق: ${link}`,
];
const plain = lines.join('\n');  // email text; Telegram gets the same lines HTML-escaped
return [{ json: { event_id: e.event_id, subject: `SecureFin: ${en} (${ref})`, plain, text: html(plain) } }];
